render_chart <- function(data, cfg, manifest) { x_col <- cfg$x %||% "longitude"; y_col <- cfg$y %||% "latitude"; size_col <- cfg$size %||% "value"; chart_validate_columns(data, list(longitude = x_col, latitude = y_col, size = size_col), c("longitude", "latitude", "size")); p <- ggplot2::ggplot(data, ggplot2::aes_string(x = x_col, y = y_col, size = size_col)) + ggplot2::geom_point(colour = cfg$color %||% "#0A84FF", alpha = 0.7) + ggplot2::scale_size_area() + ggplot2::coord_quickmap() + ggplot2::theme_minimal(base_size = 12) + ggplot2::labs(title = cfg$title %||% NULL, x = x_col, y = y_col, size = size_col); chart_open_device(cfg$outputPath, cfg$format); print(p); grDevices::dev.off(); cfg$outputPath }
